"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["89141"],{9858(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.oferta_curso_duplicada","status":422,"titulo":"Cada oferta de curso s\xf3 pode ter uma distribui\xe7\xe3o de vagas no processo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.oferta_curso_duplicada","requisitos":["UNI-REQ-0134"],"oQueAconteceu":["Duas ou mais distribui\xe7\xf5es de vagas do corpo do pedido declaram o mesmo\\n`OfertaCursoId`. Cada oferta de curso participa do processo com uma \xfanica\\ndistribui\xe7\xe3o de vagas \u2014 se ela oferece mais de uma modalidade, todas entram\\nna `modalidadeIds` dessa mesma distribui\xe7\xe3o (ver\\n[`configuracao_distribuicao_vagas.modalidades_vazias`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.modalidades_vazias)),\\nn\xe3o em distribui\xe7\xf5es separadas para a mesma oferta.","Esta confer\xeancia roda **depois** que a resolu\xe7\xe3o individual de cada distribui\xe7\xe3o\\nj\xe1 passou (oferta existe, modalidades resolvidas \u2014 ver\\n[`configuracao_distribuicao_vagas.oferta_curso_nao_encontrada`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.oferta_curso_nao_encontrada)):\\ns\xf3 nesse momento a cole\xe7\xe3o inteira de distribui\xe7\xf5es \xe9 substitu\xedda no\\nprocesso, e \xe9 a\xed que a duplicidade de oferta entre elas \xe9 conferida.","Este c\xf3digo s\xf3 \xe9 alcan\xe7\xe1vel pela **defini\xe7\xe3o de distribui\xe7\xe3o de vagas**."],"comoResolver":["Revise o corpo do pedido e garanta que cada `OfertaCursoId` apare\xe7a em no m\xe1ximo uma\\ndistribui\xe7\xe3o de vagas. Se a oferta precisa de mais de uma modalidade,\\ninclua todas na mesma distribui\xe7\xe3o, em vez de repetir a oferta em\\ndistribui\xe7\xf5es diferentes."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);